L000189		\title{Gaussian time-translation covariant operations: structure, implementation, and thermodynamics}
L000190	
L000191		\author{Xueyuan Hu}
L000192	    \email{xyhu@sdu.edu.cn}
L000193		\affiliation{\shandong}
L000194		\author{Lea Lautenbacher}
L000195	    \email{lea.lautenbacher@uni-ulm.de}
