L000498	\emph{Appendix A: Single-mode state transformations}---
L000499	It is instructive to consider the simplest case of single-mode bosonic systems.
L000500	Note that the second moments $\mu$ and $\chi$, as well as the GCO matrices $A$ and $B$ are numbers in this case.
L000501	For a single-mode second moment $(\mu,\chi)$, our monotones are given as $\Sl_{\pm}(\mu,\chi) = \frac{|\chi|}{\mu \pm \frac{1}{2}}$ when $\mu>\frac{1}{2}$ and $\Sl_{\pm}(\mu,\chi) = 0$ when $\mu=\frac{1}{2}$, corresponding to the second moment of a vacuum state.
L000502	In Figure~\ref{fig:single_mode_cone}, single-mode states are visualized in a two-dimensional plot where $\Sl_{-}$ corresponds to the slope of the line connecting the state of interest and the single mode vacuum, whereas $\Sl_{+}$ corresponds to the other slope from the $(-\frac{1}{2},0)$ point.
L000503	
L000504	Furthermore, the monotones $\Sl_{\pm}$ also become sufficient for the second moment transformation, i.e. they become a pair of complete monotones for the second moments under GCO.
L000505	\begin{lemma}
L000506		\label{le:single_mode_state}
L000507		Suppose that second moments $(\mu,\chi)$ and $(\mu',\chi')$ represent a single-mode system.
L000508	    Then, $(\mu,\chi)\toGCO(\mu',\chi')$ if and only if
L000509		\begin{align}
L000510			\Sl_{\pm}(\mu,\chi)\geq \Sl_{\pm}(\mu',\chi').\label{eq:slope}
L000511		\end{align}
L000512	\end{lemma}
L000513	\begin{proof}
L000514		The `only if' part follows directly from monotonicity of $\Sl_{\pm}$.
L000515		To prove the `if' part, we construct a GCO converting $(\mu,\chi)$ to $(\mu',\chi')$ when monotonicity is satisfied.
L000516	
L000517		Recall that the monotones $\Sl_{\pm}$ are always non-negative from (P1).
L000518		If $\chi = 0$, the monotone $0 = \Sl_{\pm}(\mu,\chi) \geq \Sl_{\pm}(\mu',\chi')$; which means that $\chi' = 0$ must hold.
L000519		Let
L000520		\begin{align}
L000521			a_{\pm}=\sqrt{\frac{\mu'\pm\frac{1}{2}}{\mu\pm\frac{1}{2}}},\ b_{\pm}=\pm\frac{1}{2}(a^2_\pm-1).
L000522		\end{align}
L000523		For $\mu'\geq \mu$, which include the case where $\mu=\frac{1}{2}$, $(\mu,0)$ can be transformed to $(\mu',0)$ by the GCO $(A,B)=(a_+,b_+)$; For $\mu'< \mu$, which implies $\mu>\frac{1}{2}$, the GCO $(A,B)=(a_-,b_-)$ transforms $(\mu,0)$ to $(\mu',0)$.
L000524		The constraint $B\geq\pm\frac{1}{2}(1-|A|^2)$ is satisfied for both cases.
L000525	
L000526		If $\chi\neq0$, the second moment transformation by a GCO $(A,B)$ reads
L000527		\begin{align}
L000528			\mu' &= |A|^{2}\mu + B,\\
L000529			\chi' &= A^{*2}\chi,
L000530		\end{align}
L000531		which can be achieved by $A=\sqrt{\chi^{\prime*}/\chi^*}$ and $B=\mu'-\mu \cdot |\chi'/\chi|$.
L000532		Since
L000533		\begin{align}
L000534			B\pm\frac{1}{2}(1-|A|^2)
L000535			&=  (\mu'\pm\frac{1}{2})-\left|\frac{\chi'}{\chi}\right|(\mu\pm\frac{1}{2})\\
L000536			&=  (\mu'\pm\frac{1}{2})\left[1-\frac{\Sl_{\pm}(\mu',\chi')}{\Sl_{\pm}(\mu,\chi)}\right]\geq0.\nonumber
L000537		\end{align}
L000538		$(A,B)$ constitutes a proper GCO.
L000539	\end{proof}
L000540	
L000541	The reachable single-mode states following Lemma~\ref{le:single_mode_state} can be represented as the blue colored region in Fig.~\ref{fig:single_mode_cone}.
L000542	
L000543	
L000544	\begin{figure}[h]
L000545		\centering
L000546		\includegraphics[width=\linewidth]{figure1.pdf}
L000547		\caption{Single-mode state transformations for the second moment $(\mu,\chi)$.
L000548			Colored parts represent the reachable states from a given initial state (red dot) via GCO (purple region), GTO (red line), and GTO with a correlated catalysis.}
L000549		\label{fig:single_mode_cone}
L000550	\end{figure}
