L000589	\section{Full characterization of Gaussian Covariant Channels}\label{ap:proofs1}
L000590	In this section we scrutinize the full characterization of Gaussian covariant channels. We begin with full generality, and first show in Proposition~\ref{pro: indep evols} that modes with non-resonant frequencies can be considered independently of each other.
L000591	
L000592	\begin{proposition}\label{pro: indep evols}
L000593		Let $F^{\omega}(S)$ be a subsystem of $S$ consisting of all bosonic modes with frequency $\omega$.
L000594		Suppose that $\mE_{\mathrm{GCO}}$ is a GCO from an $\Inm$ modes system $I$ to an $\Outm$ modes system $O$.
L000595		Then we can always write $\mE_{\mathrm{GCO}} = \mE_{3}\circ\mE_{2}\circ\mE_{1}$, i.e. as a concatenation of three GCOs:
L000596		\begin{enumerate}
L000597			\item $\mE_{1} = \Tr_{\{F^{\omega}(I)\,|\, F^{\omega}(O)=\emptyset\}}$ tracing out all input modes that do not have the output modes with the same frequency,
L000598			\item $\mE_{2} = \bigoplus_{\{\omega \,|\, F^{\omega}(I),F^{\omega}(O) \neq \emptyset\}} \mE_{\omega}$, where each $\mE_{\omega}$ is a GCO from $F^{\omega}(I)$ to $F^{\omega}(O)$ when both are non-empty, and
L000599			\item $\mE_{3}(\cdot) = \cdot\bigotimes_{\{F^{\omega}(O)\,|\, F^{\omega}(I)=\emptyset\}} \sigma_{F^{\omega}(O)}$ appending a fixed symmetric state $\sigma_{F^{\omega}(O)}$ that is independent of the input state for each output modes that do not have the input modes with the same frequency.
L000600		\end{enumerate}
L000601	\end{proposition}
L000602	\begin{proof}
L000603		Suppose that $\mE_{\mathrm{GCO}}$ is a GCO, i.e. it satisfies the covariance condition $\mE_{\mathrm{GCO}}\circ\mathcal{U}_t^\mathrm{in} = \mathcal{U}_t^\mathrm{out}\circ\mE_{\mathrm{GCO}}$ with time evolution operations $\mathcal{U}_{t}^{\mathrm{in/out}}$.
L000604		Note that the unitary processes $\mathcal{U}_t^\mathrm{in}$ and $\mathcal{U}_t^\mathrm{out}$ are associated with the tuples $(\tR_{\mathrm{in}}(t),0,0)$ and $(\tR_{\mathrm{out}}(t),0,0)$, where
L000605		\begin{align}
L000606			\tR_{\mathrm{in}}(t) = \left(\bigoplus_{i} e^{-i\omega_{i}t}\right)\oplus \left(\bigoplus_{i} e^{i\omega_{i}t}\right),\quad \tR_{\mathrm{out}}(t) = \left(\bigoplus_{i} e^{-i\omega'_{i}t}\right)\oplus \left(\bigoplus_{i} e^{i\omega'_{i}t}\right),
L000607		\end{align}
L000608		and $\{\omega_{i}\}_{i}$ and $\{\omega'_{i}\}_{i}$ are input/output frequencies.
L000609		Then $\mE_{\mathrm{GCO}}$ has an one-to-one correspondence with a tuple $(\tX,\tY,\td)$ satisfying
L000610		\begin{align}
L000611			\tX\tR_{\mathrm{in}}(t) \vecr + \td & =  \tR_{\mathrm{out}}(t)\tX \vecr+\tR_{\mathrm{out}}(t)\td, \label{eq:c1} \\
