L000693	\section{Full characterization of freely dilatable Gaussian covariant channels}\label{ap:proofs1_2}
L000694	We restate and prove Lemma~\ref{le:free_dilation} of the main text, which is our central technical result and sets a foundation for all the subsequent main results such as Theorem~\ref{th:gento_gto}, Lemma~\ref{le:single_mode_state} and Theorem~\ref{thm: no catalysis}.
L000695	We restate the lemma here as Lemma~\ref{le:free_dilation_app} for the reader's convenience.
L000696	\begin{lemma}\label{le:free_dilation_app}
L000697	A GCO $(A,B)$ is freely dilatable if and only if the following two conditions are satisfied.
L000698	\begin{itemize}
L000699	    \item[(F1)] $\iden-AA^\dagger\geq0$;
L000700	    \item[(F2)] $\supp(B)= \supp(\iden-AA^\dagger)$.
L000701	\end{itemize}
L000702	Furthermore, when (F1) or (F2) is not satisfied, even using a non-Gaussian and/or asymmetric auxiliary state does not enable the dilation with a Gaussian covariant unitary.
L000703	\end{lemma}
L000704	\begin{proof}
L000705	    If the two conditions are satisfied, the dilation in Definition~\ref{def: free dilation} can be constructed as follows.
L000706	    Let
L000707	    \begin{align}
L000708	        A=U\begin{pNiceArray}{cc}
L000709	            \sqrt{1-\Lambda_+} & 0 \\
L000710	            0 & \iden_{m-m_+}
L000711	        \end{pNiceArray}W,\label{eq:A_SVD}
L000712	    \end{align}
L000713	    be the singular value decomposition of $A$, where $\Lambda_+=\mathrm{diag}(\lambda_1,\dots,\lambda_{m_+})>0$ is a $m_+$-dimensional diagonal matrix, $m_+\leq m$, and $U,W$ are $m\times m$-dimensional unitaries.
L000714	    Then the spectral decomposition of  $\iden-AA^\dagger$ is
L000715		\begin{align}
L000716		    \iden-AA^\dagger = U\begin{pNiceArray}{cc}
L000717			        \Lambda_+ & 0 \\
L000718			        0 & 0
L000719			    \end{pNiceArray}U^\dagger\label{eq:I_AA_SVD},
L000720		\end{align}
L000721		and (F2) is then equivalent to $B$ having the form
L000722		\begin{align}
L000723		    B=U\begin{pNiceArray}{cc}
L000724			        B_+ & 0 \\
L000725			        0 & 0
L000726			    \end{pNiceArray}U^\dagger,\label{eq:B_decom}
L000727		\end{align}
L000728		where $B_+>0$ is an $m_+$-dimensional completely positive matrix.
L000729	   A straightforward calculation shows that an $m_+$-mode auxiliary state with
L000730	    \begin{align}
L000731	        \mu_R=\Lambda_+^{-\frac{1}{2}}B_+\Lambda_+^{-\frac{1}{2}},\ \qquad \chi_R=0,
L000732	    \end{align}
L000733	    and a joint unitary
L000734	    \NiceMatrixOptions{cell-space-limits = 2pt}
L000735	    \begin{align}
L000736	        V=\begin{pNiceArray}{c:c}
L000737	            U & 0 \\
L000738	            \hdottedline
L000739	            0 & \iden_{m_+}
L000740	        \end{pNiceArray}
L000741	        \begin{pNiceArray}{cc:c}
L000742	            \sqrt{1-\Lambda_+} & 0 & \sqrt{\Lambda_+} \\
L000743	            0 & \iden_{m-m_+} & 0 \\
L000744	            \hdottedline
L000745	            -\sqrt{\Lambda_+} & 0 & \sqrt{1-\Lambda_+}
L000746	        \end{pNiceArray}
L000747	        \begin{pNiceArray}{c:c}
L000748	            W & 0 \\
L000749	            \hdottedline
L000750	            0 & \iden_{m_+}
L000751	        \end{pNiceArray}\label{eq:dila_V}
L000752	    \end{align}
L000753		gives the desired dilation. Besides, the uncertainty relation $M_R+\mmZ\geq0$, which reduces to $\mu_R\geq\frac{\iden}{2}$, is ensured by the constraint $B\geq\frac{1}{2}(\iden-AA^\dagger)$.
L000754	
L000755	    Conversely, if a GCO $(A,B)$ has a free dilation $(\mu_R,0)$ and
L000756	    \begin{align}
L000757	        V=\begin{pNiceArray}{c:c}
L000758	            V_{SS} & V_{SR} \\
L000759	            \hdottedline
L000760	            V_{RS} & V_{RR}
L000761	        \end{pNiceArray},
L000762	    \end{align}
L000763	    then
L000764	    \begin{align}
L000765	        V_{SS} &=A,\label{eq:vss}\\
L000766	        V_{SR}\mu_R V_{SR}^\dagger & = B.\label{eq:vsr}
L000767	    \end{align}
L000768	    Because $\iden-V_{SS}V_{SS}^\dagger=V_{SR}V_{SR}^\dagger\geq0$, Eq. (\ref{eq:vss}) holds only if condition (F1) is satisfied. Further, because
L000769	    \begin{align}
L000770	        V_{SR}V_{SR}^\dagger=\iden-AA^\dagger=U
L000771	        \begin{pNiceArray}{cc}
L000772	        \Lambda_+ & 0 \\
L000773	        0 & 0
L000774	    \end{pNiceArray}U^\dagger,
L000775	    \end{align}
L000776	    the SVD of $V_{SR}$ reads
L000777	    \begin{align}
L000778	        V_{SR}=U
L000779	        \begin{pNiceArray}{cc}
L000780	        \sqrt{\Lambda_+} & 0 \\
L000781	        0 & 0
L000782	    \end{pNiceArray}
L000783	    U_R.
L000784	    \end{align}
L000785	    Substituting it to Eq.~\eqref{eq:vsr}, we obtain
L000786	    \begin{align}
L000787	        B= U\begin{pNiceArray}{cc}
L000788	        \sqrt{\Lambda_+} & 0 \\
L000789	        0 & 0
L000790	    \end{pNiceArray}U_R\mu_R U_R^\dagger\begin{pNiceArray}{cc}
L000791	        \sqrt{\Lambda_+} & 0 \\
L000792	        0 & 0
L000793	    \end{pNiceArray} U^\dagger,
L000794	    \end{align}
