L000804	
L000805	\begin{theorem}
L000806	\label{th:GCO_PI_app}
L000807		If a GCO mapping a system to itself has no fixed-point that is a valid quantum state, then it is not freely dilatable.
L000808		However, the converse is not true.
L000809	\end{theorem}
L000810	\begin{proof}
L000811		We prove the first claim by contrapositive.
L000812		We explicitly construct a valid fixed-point for any $m$-mode to $m$-mode GCO $(A,B)$ with a free dilation.
L000813		Define a matrix
L000814		\begin{align}
L000815			\Delta \coloneqq B-\frac{1}{2}(\iden-AA^\dagger) \geq 0,
L000816		\end{align}
L000817		where the positive semidefiniteness comes from the CP constraint $B \geq \frac{1}{2}(\iden - AA^{\dagger})$.
L000818		Next, we define
L000819		\begin{align}
L000820			\mu_{\star} \coloneqq \frac{\iden}{2} + \sum_{n=0}^{\infty} A^{n} \Delta (A^\dagger)^{n}.
L000821		\end{align}
L000822		We show that $(\mu_{\star},\chi_{\star} = 0)$ can be a valid choice of the second moment for a quantum state using the following arguments.
L000823		\begin{enumerate}
L000824	        \item A direct calculation shows $\mu_\star=A\mu_\star A^\dagger+B$.
L000825			\item $A^{n} \Delta (A^\dagger)^{n}\geq0$ for any $n\geq0$ since $\Delta\geq0$.
L000826			Thus, $\mu_{\star} \geq \frac{\iden}{2}$.
L000827			\item From Lemma~\ref{le:free_dilation_app}, we have $AA^\dagger\leq \iden$ and $\supp(\Delta)\subseteq\supp(\iden-AA^\dagger)$ meaning that $\Delta$ has support only on the strict-contraction subspace of $A$.
L000828			Hence, the series $\sum_{n=0}^{\infty} A^{n} \Delta (A^\dagger)^{n}$ converges and $\mu_{\star}$ is finite.
L000829		\end{enumerate}
L000830		Therefore the centered symmetric Gaussian state with moments $(\vec\alpha_\star=0,\mu_\star,\chi_\star=0)$ is a valid fixed point.
L000831	
L000832		For the second claim, we provide a counterexample: a GCO with a fixed-point but admits no free dilation.
L000833		Consider a two-mode GCO with
L000834		\begin{align}
L000835			A=\begin{pNiceArray}{cc}
L000836				0 & \sqrt{\eta_1} \\
L000837				\sqrt{\eta_2} & 0
L000838			\end{pNiceArray},\quad
L000839			B=\begin{pNiceArray}{cc}
L000840				b_{11} & 0 \\
L000841				0 & b_{22}
L000842			\end{pNiceArray},
L000843		\end{align}
L000844		where $\eta_1\eta_2<1$, $\eta_2>1$, and $b_{11}\geq\frac{1}{2}(1-\eta_1)$, $b_{22}\geq\frac{1}{2}(\eta_2-1)$.
L000845		The fixed-point of such a channel is
L000846		$\mu=\begin{pNiceArray}{cc}
L000847			\mu_{11} & 0 \\
L000848			0 & \mu_{22}
L000849		\end{pNiceArray}$ and $\chi=0$, where
L000850		\begin{align}
L000851			\mu_{11}=\frac{b_{11}+\eta_1 b_{22}}{1-\eta_1\eta_2},\quad
L000852			\mu_{22}=\frac{b_{22}+\eta_2 b_{11}}{1-\eta_1\eta_2}.
L000853		\end{align}
L000854		However, this channel does not admit a physical implementation, because $\eta_2>1$ violates Condition (F1) in Lemma~\ref{le:free_dilation_app}.
L000855	\end{proof}
