L000896	\begin{lemma}\label{le: fixed point decomposition}
L000897		Suppose that an $m$-mode second moment $(\mu,\chi)$ with $\chi\neq0$ is a fixed-point of a GCO $(A,B)$.
L000898		Then there exists a unitary operator $U$ such that
L000899		\begin{align}
L000900			U^{*}\chi U^{\dagger} = \hat{\chi}_{11} \oplus 0,\quad	UAU^{\dagger} = \hat{a}_{11} \oplus \hat{a}_{22},\quad UBU^{\dagger} = 0 \oplus \hat{b}_{22},
L000901		\end{align}
L000902		where the decomposition $X\oplus Y$ is such that $X$ acts on the support of $U^{*}\chi U^{\dagger}$, and $Y$ on the kernel of $U^{*}\chi U^{\dagger}$, respectively.
L000903		Furthermore, $\hat{\chi}_{11}>0$ and $\hat{a}_{11}$ is a unitary matrix.
