L001054	\section{Closure of gap between TOs and EnTOs in the Gaussian regime}\label{ap: EnTO}
L001055	In this section we prove one of our central results (Theorem \ref{th:gento_gto}, reiterated as Theorem \ref{th:gento_gto_app}), which is the fact that the gap between thermal operations and its enhanced version closes in the Gaussian regime. The proof relies largely on the full characterization of Gaussian covariant operations having their structure fully specified by the mathematical characterization of such operations, as outlined in Lemma \ref{le:free_dilation_app}.
L001056	\begin{theorem}[GEnTOs = GTOs]\label{th:gento_gto_app}
L001057	For any Gaussian enhanced thermal operation $\mE_{\mathrm{GEnTO}}$ on a system $S$, there exist an auxiliary Gibbs state $\gamma_R=\frac{e^{-\beta H_R}}{\tr(e^{-\beta H_R})}$ and a GCO unitary (i.e. a Gaussian unitary that is U(1)-covariant with respect to the Hamiltonian-generated representation) $\mathcal{U}_{\mathrm{PC}}$ acting on $SR$, such that
L001058	\begin{align}
L001059	    \mE_{\mathrm{GEnTO}}(\cdot)=\tr_R\left[\mathcal{U}_{\mathrm{PC}}(\cdot\otimes\gamma_R)\mathcal{U}_{\mathrm{PC}}^\dagger\right].
L001060	\end{align}
L001061	This implies GEnTOs and Gaussian thermal operations (GTOs) are equivalent on the level of channels.
L001062	\end{theorem}
L001063	\begin{proof}
L001064	The second moment of the Gibbs state reads $(\mu_\gamma^\beta,0)$, where $\mu_\gamma^\beta=(\bar{n}_\beta+\frac{1}{2})\iden$ and $\bar{n}_\beta=\frac{1}{e^{\beta\omega}-1}$.
L001065	The Gibbs-preserving condition is then written as
L001066	\begin{align}
L001067	    (\bar{n}_{\beta}+\frac{1}{2})AA^\dagger +B= (\bar{n}_{\beta}+\frac{1}{2})\iden.\label{eq:fix_point}
L001068	\end{align}
L001069	Condition (F1) in Lemma~\ref{le:free_dilation_app} is ensured by $B\geq0$. For condition (F2), we rewrite Eq. (\ref{eq:fix_point}) as
L001070	\begin{align}
L001071	    B=(\bar{n}_{\beta}+\frac{1}{2})(\iden-AA^\dagger).
L001072	\end{align}
L001073	It follows directly that $B_+$ and $\Lambda_+$ in Eqs. (\ref{eq:I_AA_SVD}) and (\ref{eq:B_decom}) are related as
L001074	\begin{align}
L001075	    B_+=(\bar{n}_{\beta}+\frac{1}{2})\Lambda_+.
L001076	\end{align}
L001077	Therefore, the dilation for a GCO with fixed-point $(\mu_\gamma^\beta,0)$ is $\mu_R=\mu_\gamma^\beta$ and $V$ in the form of Eq. (\ref{eq:dila_V}). In other words, any Gaussian EnTO $\mE$ can be decomposed as $\mE=\mU_L\circ\mE_D\circ\mU_R$, where $\mU_L$ and $\mU_R$ are Gaussian phase-covariant unitaries, and $\mE_D$ is realized by mixing the $j$th system mode ($j=1,\dots,m_+$) with an auxiliary mode initially in the Gibbs state at inverse temperature $\beta$ via a beam-splitter with transmittance $\eta_j=1-\lambda_j$. It means that the sets of GEnTOs and GTOs are equivalent.
L001078	\end{proof}
