L001083	\subsection{Proof of finiteness and faithfulness (P1 in main text)}
L001084	Recall the definition of monotones
L001085	\begin{align}\label{eq: Slpm def in main}
L001086		\Sl_{\pm}(\mu,\chi) \coloneqq \boldsymbol{\sigma}_{1}\left[ \left(\mu^{*}\pm\frac{\iden}{2}\right)^{-\frac{1}{2}}\chi\ \left(\mu\pm\frac{\iden}{2}\right)^{-\frac{1}{2}}\right],
L001087	\end{align}
L001088	where $(\cdot)^{-\frac{1}{2}}$ denotes the pseudoinverse of $(\cdot)^{\frac{1}{2}}$ and $\boldsymbol{\sigma}_{1}[\cdot]$ denotes the largest singular value.
L001089	By definitions of singular values and pseudoinverse, $0\leq \Sl_{\pm}(\mu,\chi) < \infty$.
L001090	
L001091	To prove the faithfulness, we need to show that $\ker(\mu\pm\frac{\iden}{2})\subseteq \ker(\chi)$.
L001092	\begin{proposition}\label{proposition: kernels inclusion}
L001093		$\ker(\mu\pm\frac{\iden}{2})\subseteq \ker(\chi)$ for any second moments of a quantum state $(\mu,\chi)$.
L001094	\end{proposition}
L001095	\begin{proof}
L001096		First, $\ker(\mu+\frac{\iden}{2})\subseteq \ker(\chi)$ is obvious from $\mu+\frac{\iden}{2}>0$.
L001097	For the second part, recall that
L001098	\begin{align}
L001099		M+\mmZ = \begin{pmatrix}
L001100			\mu^{*} + \frac{\iden}{2} & \chi\\
L001101			\chi^{*} & \mu-\frac{\iden}{2}
L001102		\end{pmatrix} \geq0,
L001103	\end{align}
L001104	from the uncertainty principle for the second moments.
L001105	For any $m$-dimensional vector $\psi^{\dagger}$, a direct calculation using the above equation shows that
L001106	\begin{align}
L001107		\begin{pmatrix}
L001108			0 & \psi
L001109		\end{pmatrix} (M+\mmZ) \begin{pmatrix}
L001110			0\\ \psi^{\dagger}
L001111		\end{pmatrix} = \psi(\mu-\frac{\iden}{2})\psi^{\dagger},
L001112	\end{align}
L001113	and since both $\mu-\frac{\iden}{2}$ and $M+\mmZ$ are positive semidefinite,
L001114	\begin{align}\label{eq: equivalence of mu and chi kers}
L001115		\psi(\mu-\frac{\iden}{2})\psi^{\dagger} = 0 \quad \iff \quad (M+\mmZ)\begin{pmatrix}
L001116			0 \\ \psi^{\dagger}
L001117		\end{pmatrix} = \begin{pmatrix}
L001118			\chi\psi^{\dagger} \\ (\mu-\frac{\iden}{2})\psi^{\dagger}
L001119		\end{pmatrix} = 0,
L001120	\end{align}
L001121	proving $\ker(\mu-\frac{\iden}{2})\subseteq \ker(\chi)$.
L001122	\end{proof}
L001123	
L001124	
L001125	On a related note, we show that without loss of generality, we can focus on states characterized by the second moments $(\mu,\chi)$ that fulfill the condition $\mu - \iden /2 > 0$, in other words, we can safely discard the modes that correspond to zero eigenvalues. This is because we show that other states that do not satisfy this condition can nevertheless be reversibly transformed via GCOs to such states.
L001126	
L001127	\begin{lemma}\label{le:vac-block-diag}
L001128		Let $(\mu,\chi)$ represent the second moment of an $m$-mode state such that $\mu-\frac{\iden}{2}$ is not positive definite.
L001129		Then there exists a unitary GCO $(V,0)$ and an $m'$-mode state with $0<m'<m$ with the second moment $(\mu'_{S'},\chi'_{S'})$ such that $V\mu V^{\dagger} = \frac{\iden}{2} \oplus \mu'_{S'}$ and $V^{*}\chi V^{\dagger} = 0 \oplus \chi'_{S'}$, where
L001130		\begin{itemize}
L001131			\item $\mu'_{S'}-\frac{\iden}{2}$ is positive definite,
L001132			\item $(\mu_{S},\chi_{S})\toGCO(\mu'_{S'},\chi'_{S'})$ and $(\mu'_{S'},\chi'_{S'}) \toGCO (\mu_{S},\chi_{S})$, i.e. the transformations between the two are reversible.
L001133		\end{itemize}
L001134	\end{lemma}
L001135	\begin{proof}
L001136		Let $V^{\dagger}$ be the unitary that transforms the kernel of $\mu-\frac{\iden}{2}$ into the first $(m-m')$ basis vectors in the usual basis.
L001137		Then the Hermitian matrix $V(\mu-\frac{\iden}{2})V^{\dagger} = 0 \oplus (\mu'_{S'} - \frac{\iden}{2})$ with some positive definite $m'\times m'$ matrix $(\mu'_{S'} - \frac{\iden}{2})>0$.
L001138		From Proposition~\ref{proposition: kernels inclusion}, we have $\ker(\mu-\frac{\iden}{2})\subseteq\ker(\chi)$, which implies $V^{*}\chi V^{\dagger} = 0 \oplus \chi'_{C'}$ with some symmetric $m'\times m'$ matrix $\chi'_{C'}$.
L001139		The transformation $(\mu_{S},\chi_{S})\toGCO(\mu'_{S'},\chi'_{S'})$ can be made by i) applying the GCO unitary $(V,0)$ and ii) tracing out the first $(m-m')$ modes.
L001140		Conversely, $(\mu'_{S'},\chi'_{S'}) \toGCO (\mu_{S},\chi_{S})$ is realized by i) appending $(m-m')$ vacuum modes and ii) applying the GCO unitary $(V^{\dagger},0)$.
L001141	\end{proof}
