L001150		For the rest of our proofs, we often use an alternative definition of $\Sl_{\pm}$ that is equivalent to Definition~\ref{def: Sl monotones} in the main text.
L001151		\begin{lemma}\label{lemma: Slpm takagi}
L001152			Let $(\mu,\chi)$ be the second moments of an $m$-mode quantum state with $\chi\neq0$.
L001153			Then
L001154			\begin{align}\label{eq: Slpm def in app}
L001155				\Sl_{\pm}(\mu,\chi)= \sup\limits_{\psi^*\chi\psi^\dagger\neq0}  \frac{|\psi^*\chi\psi^\dagger|}{\psi (\mu\pm\frac{\iden}{2})\psi^\dagger},
L001156			\end{align}
L001157			which are in the form of generalized Rayleigh quotients maximized over $m$-dimensional row vectors $\psi$.
L001158		\end{lemma}
L001159		\begin{proof}
L001160			We start from Eq.~\eqref{eq: Slpm def in main} and derive Eq.~\eqref{eq: Slpm def in app}.
L001161			Since the matrix $K_{\pm} \coloneqq (\mu^{*}\pm\frac{\iden}{2})^{-\frac{1}{2}}\chi\ (\mu\pm\frac{\iden}{2})^{-\frac{1}{2}}$ is symmetric, the largest singular value $\Sl_{\pm}(\mu,\chi)$ can be written as
L001162			\begin{align}\label{eq:Sl_pm_def_compact}
L001163				\Sl_\pm(\mu,\chi)=\sup_{\|\phi\|=1}\left|\phi^{\tp} K_{\pm} \phi\right| = \sup_{\phi}\frac{\left |\phi^{\tp}K_{\pm}\phi\right |}{\phi^{\dagger}\phi}.
L001164			\end{align}
L001165			Note that the supremum is achieved only when $\phi \in \supp(\mu\pm\frac{\iden}{2})$ because the pseudoinverse operator $(\mu\pm\frac{\iden}{2})^{-\frac{1}{2}}$ inside $K_{\pm}$ annihilate any component of $\phi$ that is not in the support of $\mu\pm\frac{\iden}{2}$.
L001166			Define $\psi^{\dagger} = (\mu\pm\frac{\iden}{2})^{-\frac{1}{2}}\phi$ and we obtain $|\phi^{\tp} K_{\pm} \phi| = |\psi^{*} \chi \psi^{\dagger}|$ for the numerator, and $\phi^{\dagger}\phi = \psi (\mu\pm\frac{\iden}{2})\psi^\dagger$ for the denominator using $\phi \in \supp(\mu\pm\frac{\iden}{2})$.
L001167			Now we can write
L001168			\begin{align}\label{eq: Slpm def with constraints}
L001169				\Sl_{\pm}(\mu,\chi)= \sup\limits_{\psi^{\dagger}\in\supp(\mu\pm\frac{\iden}{2})}  \frac{|\psi^*\chi\psi^\dagger|}{\psi (\mu\pm\frac{\iden}{2})\psi^\dagger} = \sup\limits_{\substack{\psi^{\dagger}\in\supp(\mu\pm\frac{\iden}{2})\\ \psi^*\chi\psi^\dagger\neq0}}  \frac{|\psi^*\chi\psi^\dagger|}{\psi (\mu\pm\frac{\iden}{2})\psi^\dagger},
L001170			\end{align}
L001171			where the second equality follows from the fact that $\Sl_{\pm}(\mu,\chi)\geq0$ and $\psi^*\chi\psi^\dagger=0$ gives $\Sl_{\pm}(\mu,\chi) = 0$.
L001172			The only difference between Eqs.~\eqref{eq: Slpm def in app} and~\eqref{eq: Slpm def with constraints} is the additional constraint $\psi^{\dagger}\in\supp(\mu\pm\frac{\iden}{2})$ for the latter.
L001173	
L001174			A general vector $\tilde{\psi}^{\dagger}$ can be written as $\tilde{\psi}^{\dagger} = \psi^{\dagger} + \zeta^{\dagger}$ where $\psi^{\dagger}\in\supp(\mu\pm\frac{\iden}{2})$ and $\zeta^{\dagger}\in\ker(\mu\pm\frac{\iden}{2})$.
L001175			We substitute $\psi^{\dagger}$ with this $\tilde{\psi}^{\dagger}$ in the RHS of Eq.~\eqref{eq: Slpm def in app}.
L001176			Proposition~\ref{proposition: kernels inclusion} implies that $\chi\zeta^{\dagger} = 0$ and $\frac{|\tilde{\psi}^*\chi\tilde{\psi}^\dagger|}{\tilde{\psi} (\mu\pm\frac{\iden}{2})\tilde{\psi}^\dagger} = \frac{|\psi^*\chi\psi^\dagger|}{\psi (\mu\pm\frac{\iden}{2})\psi^\dagger}$.
L001177			Therefore, the additional constraint $\psi^{\dagger}\in\supp(\mu\pm\frac{\iden}{2})$ does not change the supremum value of Eq.~\eqref{eq: Slpm def in app}, and we prove the desired equivalence.
L001178		\end{proof}
