L001180	
L001181	Now we prove the monotonicity of $\Sl_{\pm}$ using Lemma~\ref{lemma: Slpm takagi}.
L001182	
L001183	\begin{lemma}[GCO monotones]\label{le:monotones_app}
L001184		Whenever $(\mu,\chi)\toGCO(\mu',\chi')$ is possible for some $\Inm$-mode and $\Outm$-mode systems $(\mu,\chi)$ and $(\mu',\chi')$, then
L001185	    \begin{align}
L001186	        \Sl_{\pm}(\mu,\chi)\geq\Sl_{\pm}(\mu',\chi').
L001187	    \end{align}
L001188	\end{lemma}
L001189	\begin{proof}
L001190		Suppose that $(\mu,\chi)\toGCO(\mu',\chi')$.
L001191		From Lemma~\ref{le:gene_GCO_app} and the uncertainty principle, we have that the initial and final second moments are related to each other by
L001192		\begin{align}
L001193			\mu'\pm\frac{\iden}{2 }& \geq  A(\mu\pm\frac{\iden}{2})A^\dagger \geq 0, \label{eq:mup_vs_mu}\\
L001194			\chi' & =  A^*\chi A^\dagger.\label{eq:chip_vs_chi}
L001195		\end{align}
L001196		Suppose that $\bar\psi$ is the optimal vector for the form of $\Sl_{\pm}$ in Eq.~\eqref{eq: Slpm def in app} achieving
L001197		\begin{align}
