L001260	\begin{lemma}\label{le: catalyst-vac-removal}
L001261		Suppose that a GCO process $(\mu_{S},\chi_{S}) \to (\mu'_{S},\chi'_{S})$ can be achieved by a catalyst $(\mu_{C},\chi_{C})$.
L001262		Then this process can also be achieved by a catalyst $(\tilde{\mu}_{C'},\tilde{\chi}_{C'})$, such that $\tilde{\mu}_{C'}>\frac{\iden}{2}$.
L001263	\end{lemma}
L001264	\begin{proof}
L001265		Suppose that $\mu_{C}-\frac{\iden}{2}$ is not positive definite.
L001266		Then Lemma~\ref{le:vac-block-diag} applies, and we can write
L001267		\begin{align}
L001268			V\mu_{C}V^{\dagger} = \frac{\iden}{2} \oplus \tilde{\mu}_{C'},\quad V^{*}\chi_{C} V^{\dagger} = 0 \oplus \tilde{\chi}_{C'},
L001269		\end{align}
L001270		with a unitary $V$, for some $(\tilde{\mu}_{C'}, \tilde{\chi}_{C'})$ with $\tilde{\mu}_{C'}>\frac{\iden}{2}$.
L001271		Denote the original GCO applied to $(\mu_{S}\oplus\mu_{C},\chi_{S}\oplus\chi_{C})$ as $(A,B)$.
L001272		We can construct the following catalytic process starting from $(\mu_{S}\oplus\tilde{\mu}_{C'},\chi_{S}\oplus\tilde{\chi}_{C'})$:
L001273		\begin{enumerate}
L001274			\item Append some vacuum modes to obtain $(\mu_{S}\oplus\frac{\iden}{2} \oplus \tilde{\mu}_{C'},\chi_{S}\oplus0 \oplus \tilde{\chi}_{C'})$.
L001275			\item Apply the unitary GCO $(\iden\oplus V^{\dagger},0)$ to obtain $(\mu_{S}\oplus\mu_{C},\chi_{S}\oplus\chi_{C})$.
L001276			\item Apply the GCO $(A,B)$ to obtain the desired system marginal moments $(\mu'_{S},\chi'_{S})$ while keeping the catalyst marginal moments $(\mu_{C},\chi_{C})$.
L001277			\item Apply the unitary GCO $(0\oplus V,0)$ to transform catalyst moments to be $(\frac{\iden}{2} \oplus \tilde{\mu}_{C'},0 \oplus \tilde{\chi}_{C'})$.
L001278			\item Remove vacuum modes and retrieve the catalyst $(\tilde{\mu}_{C'},\tilde{\chi}_{C'})$.
L001279		\end{enumerate}
L001280		Since all five steps are valid GCOs, the lemma statement holds true.
L001281	\end{proof}
