L001453			\mu_{C}\pm\frac{\iden}{2} & =  \sum_{j=0}^{N} (a_{CC})^{j} [a_{CS}(\mu_{S} \pm \frac{\iden}{2})a_{CS}^{\dagger}+\Delta_{\pm} ](a_{CC}^{\dagger})^{j} + (a_{CC})^{N+1} (\mu_{C}\pm\frac{\iden}{2})(a_{CC}^{\dagger})^{N+1},\\
L001454			\chi_{C} & =  \sum_{j=0}^{N} (a_{CC}^{*})^{j} a^{*}_{CS} \chi_{S} a_{CS}^{\dagger} (a_{CC}^{\dagger})^{j} + (a_{CC}^{*})^{N+1}\chi_{C}(a_{CC}^{\dagger})^{N+1},
L001455		\end{align}
L001456		for any $N$ by repeatedly replacing $\mu_{C}$ and $\chi_{C}$ in the RHS expression of the equations.
L001457		If there exists $j>0$ such that either $\psi^{*}(a_{CC}^{*})^{j} a^{*}_{CS} \chi_{S} a_{CS}^{\dagger} (a_{CC}^{\dagger})^{j}\psi^{\dagger}\neq0$ or $\psi(a_{CC})^{j} \Delta_{\pm} (a_{CC}^{\dagger})^{j}\psi^{\dagger}\neq0$, we prove the desired inequality by the argument used for \textbf{Case 2}.
L001458		Otherwise, we have
L001459		\begin{align}
L001460			\psi(\mu_{C}\pm\frac{\iden}{2})\psi^{\dagger} &= \psi (a_{CC})^{N}(\mu_{C}\pm\frac{\iden}{2})(a_{CC}^{\dagger})^{N} \psi^{\dagger},\label{eq: psi aCC N 1}\\
L001461			\psi^{*}\chi_{C}\psi^{\dagger} &= \psi^{*} (a_{CC}^{*})^{N}\chi_{C}(a_{CC}^{\dagger})^{N} \psi^{\dagger},\label{eq: psi aCC N 2}
L001462		\end{align}
L001463		for any $N$.
L001464		This implies that a vector space $\mathcal{V} \coloneqq \mathrm{span}\{(a_{CC}^{\dagger})^{N} \psi^{\dagger} | N\geq0\}$ is an invariant subspace under the application of $a_{CC}^{\dagger}$, and the matrix $a_{CC}$ and the column vector $\psi^{\dagger}$ have the block form
L001465		\begin{align}
L001466			a_{CC} = \begin{pNiceArray}{c:c}
L001467				a_{VV} & 0\\
L001468				\hdottedline
L001469				a_{WV} & a_{WW}
L001470			\end{pNiceArray}, \quad \psi^{\dagger} = \begin{pNiceArray}{c}
L001471				\psi_{V}^{\dagger} \\ \hdottedline 0
L001472			\end{pNiceArray},
L001473		\end{align}
L001474		where $a_{VV}$ maps $\mathcal{V}$ into itself.
L001475		Finally, we assume, without loss of generality, that $\mu_{S}\pm \frac{\iden}{2}>0$ using Lemma~\ref{le:vac-block-diag}.
L001476		Then, the condition $\psi(a_{CC})^{N}a_{CS}(\mu_{S}\pm\frac{\iden}{2})a_{CS}^{\dagger}(a_{CC}^{\dagger})^{N}\psi^{\dagger} = 0$ for any $N\geq0$ implies that $a_{CS}(\mu_{S}\pm\frac{\iden}{2})a_{CS}^{\dagger}$ has no support in $\mathcal{V}$.
L001477		In other words, $a_{CS}$ is in the block form $a_{CS}^{\dagger} = \begin{pNiceArray}{c:c} 0 & a_{WS}^{\dagger} \end{pNiceArray}$.
L001478	
L001479		Now we rewrite the block form of $A$
L001480		\begin{align}
L001481			A = \begin{pNiceArray}{c:c:c}
L001482				a_{SS} & a_{SV} & a_{SW}\\
L001483				\hdottedline
L001484				0 & a_{VV} & 0\\
L001485				\hdottedline
L001486				a_{WS} & a_{WV} & a_{WW}
L001487			\end{pNiceArray}.
L001488		\end{align}
L001489		Recall the catalyst recovery conditions Eqs.~\eqref{eq:cat-condition-1} and~\eqref{eq:cat-condition-2}.
L001490		If we restrict our attention to $\mathcal{V}$ subspace, the following equalities hold
L001491		\begin{align}
L001492			\mu_{VV} &= a_{VV}\mu_{VV}a_{VV}^{\dagger} + b_{VV},\\
L001493			\chi_{VV} &= a_{VV}^{*}\chi_{VV}a_{VV}^{\dagger}.
L001494		\end{align}
L001495		These equations imply that $(\mu_{VV},\chi_{VV})$ is the fixed-point of a GCO $(a_{VV},b_{VV})$.
L001496		Applying Lemma~\ref{le: fixed point decomposition}, another block decomposition
L001497		\begin{align}\label{eq: V1 is separated}
L001498			A = \begin{pNiceArray}{c:c:c:c}
L001499				a_{SS} & 0 & a_{SV_{2}} & a_{SW}\\
L001500				\hdottedline
L001501				0 & a_{V_{1}V_{1}} & 0 & 0\\
L001502				\hdottedline
L001503				0 & 0 & a_{V_{2}V_{2}} & 0\\
L001504				\hdottedline
L001505				a_{WS} & 0 & a_{WV_{2}} & a_{WW}
L001506			\end{pNiceArray},\quad
L001507			B = \begin{pNiceArray}{c:c:c:c}
L001508				b_{SS} & 0 & b_{SV_{2}} & b_{SW}\\
L001509				\hdottedline
L001510				0 & 0 & 0 & 0\\
L001511				\hdottedline
L001512				b_{V_{2}S} & 0 & b_{V_{2}V_{2}} & b_{V_{2}W}\\
L001513				\hdottedline
L001514				b_{WS} & 0 & b_{WV_{2}} & b_{WW}
L001515			\end{pNiceArray},
L001516		\end{align}
L001517		are derived.
L001518	    Here $V_1$ and $V_2$ are divided such that $\chi_{VV}=\chi_{V_1V_1}\oplus 0_{V_2V_2}$. Because $\chi_{VV}\neq0$, $\dim(a_{V1V1})\geq1$.
L001519		Note that we already used $B\geq\pm\frac{1}{2}(\iden - AA^{\dagger})$ condition to remove all blocks of $A$ and $B$ containing $V_{1}$ as an index, except for the unitary matrix $a_{V_{1}V_{1}}$.
L001520		Eq.~\eqref{eq: V1 is separated} indicates that modes in $V_{1}$ block evolve unitarily and independently from all other modes.
L001521		Hence, there exists a catalyst $(\mu'_{C'},\chi'_{C'})$ and a GCO $(A',B')$ that can achieve the same state transformations and they are given by
L001522		\begin{align}
L001523			A' = \begin{pNiceArray}{c:c:c}
L001524				a_{SS}  & a_{SV_{2}} & a_{SW}\\
L001525				\hdottedline
L001526				0  & a_{V_{2}V_{2}} & 0\\
L001527				\hdottedline
L001528				a_{WS}  & a_{WV_{2}} & a_{WW}
L001529			\end{pNiceArray},\quad
L001530			B' = \begin{pNiceArray}{c:c:c}
L001531				b_{SS} & b_{SV_{2}} & b_{SW}\\
L001532				\hdottedline
L001533				b_{V_{2}S} & b_{V_{2}V_{2}} & b_{V_{2}W}\\
L001534				\hdottedline
L001535				b_{WS} & b_{WV_{2}} & b_{WW}
L001536			\end{pNiceArray},\quad
L001537			\mu'_{C'} = \begin{pNiceArray}{c:c}
L001538				\mu_{V_{2}V_{2}} & \mu_{V_{2}W}\\
L001539				\hdottedline
L001540				\mu_{WV_{2}} & \mu_{WW}
L001541			\end{pNiceArray},\quad
L001542			\chi'_{C'} = \begin{pNiceArray}{c:c}
L001543				0 & \chi_{V_{2}W} \\
L001544				\hdottedline
L001545				\chi_{WV_{2}} & \chi_{WW}
L001546			\end{pNiceArray}.
L001547		\end{align}
L001548		Therefore we can repeat the same argument iteratively until i) \textbf{Case 3-1} can be applied and the proof is concluded or ii) catalyst state is reduced to a single mode and either \textbf{Case 2} or \textbf{Case 3-1} is true.
L001549	\end{proof}
